struct PreferenceObserver { darling_windows_preferences_observer callback; void* context; };
struct darling_windows_preferences { std::filesystem::path path; std::map<std::string,std::string> values; std::map<std::string,std::string> arguments; std::map<std::string,std::string> registration; std::vector<PreferenceObserver> observers; std::recursive_mutex mutex; std::filesystem::file_time_type observed_write{}; HANDLE event_handle{}; bool argument_domain{}; bool managed_domain{}; };
