std::string Esc(const std::string& v){std::string o;for(char c:v){if(c=='&')o+="&amp;";else if(c=='<')o+="&lt;";else if(c=='>')o+="&gt;";else if(c=='\"')o+="&quot;";else if(c=='\'')o+="&apos;";else o+=c;}return o;}
std::string Unesc(std::string v){const std::pair<const char*,const char*> e[]={{"&amp;","&"},{"&lt;","<"},{"&gt;",">"},{"&quot;","\""},{"&apos;","'"}};for(auto [a,b]:e)for(size_t p=0;(p=v.find(a,p))!=std::string::npos;){v.replace(p,std::strlen(a),b);p+=std::strlen(b);}return v;}
bool Valid(const char* s){if(!s||!*s)return false;for(unsigned char c:std::string(s))if(!(std::isalnum(c)||c=='.'||c=='-'||c=='_'))return false;return true;}
std::filesystem::path Prefix(){char b[32768]{};auto n=GetEnvironmentVariableA("WINTOSH_GUEST_PREFIX",b,sizeof b);return n&&n<sizeof b?std::filesystem::u8path(std::string(b,n)):std::filesystem::path();}
bool Load(darling_windows_preferences& s){auto source=s.path;std::ifstream f(source,std::ios::binary);if(!f){source=s.path.wstring()+L".tmp";f.open(source,std::ios::binary);}if(!f)return true;std::string x((std::istreambuf_iterator<char>(f)),{});std::regex r(R"(<key>([^<]+)</key>\s*<(string|integer|true|false)>([^<]*)</(string|integer|true|false)>)");for(std::sregex_iterator i(x.begin(),x.end(),r),e;i!=e;++i)if((*i)[2].str()==(*i)[4].str())s.values[Unesc((*i)[1].str())]=(*i)[2].str()=="string"?std::string("s:")+Unesc((*i)[3].str()):(*i)[2].str()=="integer"?std::string("i:")+(*i)[3].str():std::string("b:")+((*i)[2].str()=="true"?"1":"0");return true;}
bool Save(darling_windows_preferences& s){std::error_code ec;std::filesystem::create_directories(s.path.parent_path(),ec);auto t=s.path.wstring()+L".tmp";std::ofstream f(std::filesystem::path(t),std::ios::binary|std::ios::trunc);if(!f)return false;f<<"<?xml version=\"1.0\" encoding=\"UTF-8\"?><plist version=\"1.0\"><dict>";for(auto&[k,v]:s.values){f<<"<key>"<<Esc(k)<<"</key>";if(v.rfind("s:",0)==0)f<<"<string>"<<Esc(v.substr(2))<<"</string>";else if(v.rfind("i:",0)==0)f<<"<integer>"<<v.substr(2)<<"</integer>";else f<<(v=="b:1"?"<true></true>":"<false></false>");}f<<"</dict></plist>";f.close();if(MoveFileExW(t.c_str(),s.path.wstring().c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))return true;ec.clear();std::filesystem::copy_file(std::filesystem::path(t),s.path,std::filesystem::copy_options::overwrite_existing,ec);std::filesystem::remove(std::filesystem::path(t),ec);return !ec;}
bool AppendEvent(const darling_windows_preferences& s,const char* key){if(!key||!*key)return true;std::ofstream f(std::filesystem::path(s.path.wstring()+L".events"),std::ios::app|std::ios::binary);if(!f)return false;f<<key<<'\n';return static_cast<bool>(f);}
std::wstring EventName(const std::filesystem::path& path){return std::wstring(L"Local\\WintoshPreferencesEvent-")+std::to_wstring(std::hash<std::wstring>{}(path.wstring()));}
bool SaveLocked(darling_windows_preferences& s,const char* changed_key=nullptr){if(s.argument_domain||s.managed_domain)return false;const auto name=std::wstring(L"Local\\WintoshPreferences-")+std::to_wstring(std::hash<std::wstring>{}(s.path.wstring()));HANDLE lock=CreateMutexW(nullptr,FALSE,name.c_str());if(!lock)return false;const bool acquired=WaitForSingleObject(lock,5000)==WAIT_OBJECT_0;const bool result=acquired&&Save(s)&&(changed_key==nullptr||AppendEvent(s,changed_key));if(result){HANDLE event_handle=CreateEventW(nullptr,FALSE,FALSE,EventName(s.path).c_str());if(event_handle){SetEvent(event_handle);CloseHandle(event_handle);}}if(acquired)ReleaseMutex(lock);CloseHandle(lock);return result;}
void OpenEvent(darling_windows_preferences& s){if(s.event_handle)CloseHandle(s.event_handle);s.event_handle=CreateEventW(nullptr,FALSE,FALSE,EventName(s.path).c_str());}
void Notify(darling_windows_preferences& s,const char* key){const auto observers=s.observers;for(const auto& observer:observers)if(observer.callback)observer.callback(key,observer.context);}
