extern "C" darling_windows_preferences_ref darling_windows_preferences_open(const char* d){if(!Valid(d))return nullptr;auto p=Prefix();if(p.empty())return nullptr;auto*s=new darling_windows_preferences;s->path=p/L"Users"/L"Default"/L"Library"/L"Preferences"/(std::filesystem::u8path(std::string(d)+".plist"));if(!Load(*s)){delete s;return nullptr;}OpenEvent(*s);if(!s->event_handle){delete s;return nullptr;}return s;}
extern "C" darling_windows_preferences_ref darling_windows_preferences_open_arguments(const char* d,int argc,const char*const*argv){auto*s=darling_windows_preferences_open(d);if(!s||argc<0){delete s;return nullptr;}s->argument_domain=true;for(int n=0;n<argc;++n){if(!argv||!argv[n])continue;std::string token=argv[n];if(token.rfind("--",0)==0)token.erase(0,2);const auto split=token.find('=');if(split==std::string::npos||!Valid(token.substr(0,split).c_str()))continue;const std::string raw=token.substr(split+1);s->arguments[token.substr(0,split)]=(raw.rfind("i:",0)==0||raw.rfind("b:",0)==0)?raw:std::string("s:")+raw;}return s;}
extern "C" darling_windows_preferences_ref darling_windows_preferences_open_suite(const char* d,const char* suite){if(!Valid(d)||!Valid(suite))return nullptr;auto*s=darling_windows_preferences_open(d);if(!s)return nullptr;s->path=s->path.parent_path()/(std::filesystem::u8path(std::string(d)+"."+suite+".plist"));s->values.clear();Load(*s);OpenEvent(*s);if(!s->event_handle){delete s;return nullptr;}return s;}
extern "C" void darling_windows_preferences_close(darling_windows_preferences_ref s){if(s){darling_windows_preferences_synchronize(s);if(s->event_handle)CloseHandle(s->event_handle);delete s;}}
extern "C" bool darling_windows_preferences_get_string(darling_windows_preferences_ref s,const char*k,char*o,size_t n){if(!s||!k||!o||!n)return false;std::lock_guard l(s->mutex);std::string value;auto i=s->values.find(k);if(i!=s->values.end())value=i->second;else{auto a=s->arguments.find(k);if(a!=s->arguments.end())value=a->second;else{auto r=s->registration.find(k);if(r!=s->registration.end())value=r->second;}}if(value.rfind("s:",0)!=0||value.size()-2>=n)return false;memcpy(o,value.data()+2,value.size()-2);o[value.size()-2]=0;return true;}
extern "C" bool darling_windows_preferences_register_string(darling_windows_preferences_ref s,const char*k,const char*v){if(!s||!Valid(k)||!v)return false;std::lock_guard l(s->mutex);if(s->values.find(k)==s->values.end())s->registration[k]=std::string("s:")+v;return true;}
extern "C" bool darling_windows_preferences_register_integer(darling_windows_preferences_ref s,const char*k,int64_t v){if(!s||!Valid(k))return false;std::lock_guard l(s->mutex);if(s->values.find(k)==s->values.end())s->registration[k]="i:"+std::to_string(v);return true;}
extern "C" bool darling_windows_preferences_register_boolean(darling_windows_preferences_ref s,const char*k,bool v){if(!s||!Valid(k))return false;std::lock_guard l(s->mutex);if(s->values.find(k)==s->values.end())s->registration[k]=v?"b:1":"b:0";return true;}
extern "C" bool darling_windows_preferences_get_integer(darling_windows_preferences_ref s,const char*k,int64_t*v){if(!s||!k||!v)return false;std::lock_guard l(s->mutex);std::string value;auto i=s->values.find(k);if(i!=s->values.end())value=i->second;else{auto a=s->arguments.find(k);if(a!=s->arguments.end())value=a->second;else{auto r=s->registration.find(k);if(r!=s->registration.end())value=r->second;}}if(value.rfind("i:",0)!=0)return false;try{*v=std::stoll(value.substr(2));return true;}catch(...){return false;}}
extern "C" bool darling_windows_preferences_get_boolean(darling_windows_preferences_ref s,const char*k,bool*v){if(!s||!k||!v)return false;std::lock_guard l(s->mutex);std::string value;auto i=s->values.find(k);if(i!=s->values.end())value=i->second;else{auto a=s->arguments.find(k);if(a!=s->arguments.end())value=a->second;else{auto r=s->registration.find(k);if(r!=s->registration.end())value=r->second;}}if(value.rfind("b:",0)!=0)return false;*v=value=="b:1";return true;}
extern "C" bool darling_windows_preferences_set_string(darling_windows_preferences_ref s,const char*k,const char*v){if(!s||!Valid(k)||!v)return false;std::lock_guard l(s->mutex);s->values[k]=std::string("s:")+v;const bool ok=SaveLocked(*s,k);if(ok)Notify(*s,k);return ok;}
extern "C" bool darling_windows_preferences_set_integer(darling_windows_preferences_ref s,const char*k,int64_t v){if(!s||!Valid(k))return false;std::lock_guard l(s->mutex);s->values[k]="i:"+std::to_string(v);const bool ok=SaveLocked(*s,k);if(ok)Notify(*s,k);return ok;}
extern "C" bool darling_windows_preferences_set_boolean(darling_windows_preferences_ref s,const char*k,bool v){if(!s||!Valid(k))return false;std::lock_guard l(s->mutex);s->values[k]=v?"b:1":"b:0";const bool ok=SaveLocked(*s,k);if(ok)Notify(*s,k);return ok;}
extern "C" bool darling_windows_preferences_remove(darling_windows_preferences_ref s,const char*k){if(!s||!k)return false;std::lock_guard l(s->mutex);s->values.erase(k);return SaveLocked(*s,k);}
extern "C" bool darling_windows_preferences_synchronize(darling_windows_preferences_ref s){if(!s)return false;std::lock_guard l(s->mutex);return SaveLocked(*s);}
extern "C" darling_windows_preferences_ref darling_windows_preferences_open_managed(const char* d){auto*s=darling_windows_preferences_open(d);if(!s)return nullptr;s->path=s->path.parent_path().parent_path().parent_path().parent_path().parent_path()/L"Library"/L"Managed Preferences"/(std::filesystem::u8path(std::string(d)+".plist"));s->values.clear();std::ifstream f(s->path,std::ios::binary);if(f){std::string x((std::istreambuf_iterator<char>(f)),{});std::regex r(R"(<key>([^<]+)</key>\s*<(string|integer|true|false)>([^<]*)</(string|integer|true|false)>)");for(std::sregex_iterator i(x.begin(),x.end(),r),e;i!=e;++i)if((*i)[2].str()==(*i)[4].str())s->values[Unesc((*i)[1].str())]=(*i)[2].str()=="string"?std::string("s:")+Unesc((*i)[3].str()):(*i)[2].str()=="integer"?std::string("i:")+(*i)[3].str():std::string("b:")+((*i)[2].str()=="true"?"1":"0");}s->managed_domain=true;return s;}
extern "C" darling_windows_preferences_ref darling_windows_preferences_open_effective(const char* d){auto*application=darling_windows_preferences_open(d);if(!application)return nullptr;auto*managed=darling_windows_preferences_open_managed(d);if(managed){for(const auto& entry:managed->values)application->values[entry.first]=entry.second;application->managed_domain=true;darling_windows_preferences_close(managed);}return application;}
extern "C" bool darling_windows_preferences_add_observer(darling_windows_preferences_ref s,darling_windows_preferences_observer callback,void* context){if(!s||!callback)return false;std::lock_guard l(s->mutex);s->observers.push_back({callback,context});return true;}
extern "C" bool darling_windows_preferences_remove_observer(darling_windows_preferences_ref s,darling_windows_preferences_observer callback,void* context){if(!s||!callback)return false;std::lock_guard l(s->mutex);const auto old=s->observers.size();s->observers.erase(std::remove_if(s->observers.begin(),s->observers.end(),[&](const PreferenceObserver& o){return o.callback==callback&&o.context==context;}),s->observers.end());return old!=s->observers.size();}
extern "C" bool darling_windows_preferences_poll_external(darling_windows_preferences_ref s,bool* changed){if(!s||!changed||s->argument_domain||s->managed_domain)return false;std::lock_guard l(s->mutex);std::error_code ec;const auto current=std::filesystem::last_write_time(s->path,ec);if(ec){*changed=false;return false;}if(s->observed_write==std::filesystem::file_time_type{}){s->observed_write=current;*changed=false;return true;}if(current==s->observed_write){*changed=false;return true;}s->observed_write=current;const auto previous=s->values;const bool loaded=Load(*s);*changed=loaded&&previous!=s->values;return loaded;}
extern "C" bool darling_windows_preferences_signal_external(darling_windows_preferences_ref s){if(!s||!s->event_handle)return false;return SetEvent(s->event_handle)!=0;}
extern "C" bool darling_windows_preferences_wait_external(darling_windows_preferences_ref s,unsigned timeout_ms,bool* changed){if(!s||!changed||s->argument_domain||s->managed_domain||!s->event_handle)return false;const DWORD result=WaitForSingleObject(s->event_handle,timeout_ms);if(result==WAIT_TIMEOUT){*changed=false;return true;}if(result!=WAIT_OBJECT_0){*changed=false;return false;}return darling_windows_preferences_poll_external(s,changed);}
extern "C" bool darling_windows_preferences_drain_external_event(darling_windows_preferences_ref s,char* key,size_t capacity,bool* has_event){if(!s||!key||!capacity||!has_event||s->argument_domain||s->managed_domain)return false;std::lock_guard l(s->mutex);*has_event=false;key[0]=0;const auto events=std::filesystem::path(s->path.wstring()+L".events");std::ifstream f(events,std::ios::binary);if(!f)return true;std::string first;std::getline(f,first);if(first.empty()&&f.eof())return true;std::string rest((std::istreambuf_iterator<char>(f)),{});f.close();if(first.size()+1>capacity)return false;std::ofstream out(events,std::ios::binary|std::ios::trunc);if(!out)return false;out<<rest;out.close();std::memcpy(key,first.data(),first.size());key[first.size()]=0;*has_event=true;return true;}
